built-in-agent::channels-agent-setup.source:
The Built-in Agent runs in the same Node.js process as Channels, so it does
not need an `AGENT_URL` or a second server. Follow the
[Built-in Agent quickstart](/quickstart) to configure your model provider,
then use the Runtime package already installed by the Channels runner.

Create a new agent for each channel thread:

```ts title="agent.ts"
import { BuiltInAgent } from "@copilotkit/runtime/v2";

export function makeAgent(threadId: string) {
  const agent = new BuiltInAgent({
    model: "openai:gpt-5.4-mini",
  });
  agent.threadId = threadId;
  return agent;
}
```

claude-sdk-python::channels-agent-setup.source:
Follow the [Claude Agent SDK Python quickstart](/claude-sdk-python/quickstart)
to configure the agent. Keep the AG-UI server created by your chosen
quickstart path running on port 8000.

The Claude adapter is mounted at the server root:

```dotenv title=".env"
AGENT_URL=http://localhost:8000/
```

Install the HTTP adapter in the Channels runner:

```bash title="Channels runner"
npm install @ag-ui/client@0.0.59
```

Create a new HTTP adapter for every channel thread:

```ts title="agent.ts"
import { HttpAgent } from "@ag-ui/client";

export function makeAgent(threadId: string) {
  const agent = new HttpAgent({ url: process.env.AGENT_URL! });
  agent.threadId = threadId;
  return agent;
}
```

claude-sdk-typescript::tool-rendering-se.source:
The agent must also register this schema as an executable backend tool. This
setup shows the connection.

<Steps>
  <Step>
    ### Connect the adapter to the MCP server

    `buildBackendToolServer` converts the tool schemas from the agent. The
    `ClaudeAgentAdapter` receives the resulting `mcpServers` and
    `allowedTools` values.


~~~~typescript title="claude-agent-sdk-adapter.ts"
function createClaudeAgentAdapter({
  toolSchemas,
  emit,
  getState,
  setState,
  executeTool,
  model,
  systemPrompt,
}: {
  toolSchemas: Anthropic.Tool[];
  emit: Emit;
  getState: () => Record<string, unknown>;
  setState: (state: Record<string, unknown>) => void;
  executeTool: ExecuteTool;
  model: string;
  systemPrompt: string;
}) {
  const backendToolServer = buildBackendToolServer({
    toolSchemas,
    emit,
    getState,
    setState,
    executeTool,
  });

  return new ClaudeAgentAdapter({
    agentId: "claude-sdk-typescript",
    model: normalizeClaudeAgentSdkModel(model),
    systemPrompt,
    tools: [],
    mcpServers: backendToolServer.mcpServers,
    allowedTools: backendToolServer.allowedTools,
    permissionMode: "dontAsk",
    maxTurns: 10,
  });
}
~~~~

  </Step>

  <Step>
    ### Register the executable tool handlers

    Each schema becomes an `sdkTool` that calls its executable CopilotKit
    handler. `createSdkMcpServer` registers these tools. The allowlist uses
    their fully qualified `mcp__copilotkit__*` names.


~~~~typescript title="claude-agent-sdk-adapter.ts"
const COPILOTKIT_MCP_SERVER_NAME = "copilotkit";
const COPILOTKIT_TOOL_PREFIX = `mcp__${COPILOTKIT_MCP_SERVER_NAME}__`;

function buildBackendToolServer({
  toolSchemas,
  emit,
  getState,
  setState,
  executeTool,
}: {
  toolSchemas: Anthropic.Tool[];
  emit: Emit;
  getState: () => Record<string, unknown>;
  setState: (state: Record<string, unknown>) => void;
  executeTool: ExecuteTool;
}): {
  mcpServers?: Record<string, McpServerConfig>;
  allowedTools: string[];
} {
  if (toolSchemas.length === 0) {
    return { allowedTools: [] };
  }

  const tools = toolSchemas.map((schema) =>
    sdkTool(
      schema.name,
      schema.description ?? "",
      zodShapeFromJsonSchema(schema.input_schema),
      async (args) => {
        try {
          const result = await executeTool(
            schema.name,
            args as Record<string, unknown>,
            getState(),
            emit,
          );
          if (result.state) {
            setState(result.state);
          }
          return {
            content: [{ type: "text" as const, text: result.resultText }],
          };
        } catch (error) {
          const message =
            error instanceof Error ? error.message : String(error);
          return {
            content: [{ type: "text" as const, text: message }],
            isError: true,
          };
        }
      },
    ),
  );

  return {
    mcpServers: {
      [COPILOTKIT_MCP_SERVER_NAME]: createSdkMcpServer({
        name: COPILOTKIT_MCP_SERVER_NAME,
        version: "1.0.0",
        tools,
      }),
    },
    allowedTools: toolSchemas.map(
      (schema) => `${COPILOTKIT_TOOL_PREFIX}${schema.name}`,
    ),
  };
}
~~~~

  </Step>
</Steps>

<Callout type="info">
  This MCP path handles compatible requests that use backend tools only.
  Requests with frontend tools, structured user content, or extended thinking
  use the direct Anthropic path. Requests with aimock transport also use this
  fallback.
</Callout>

